DROP TABLE IF EXISTS `daily_train_carriage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_train_carriage` (
  `id` bigint NOT NULL COMMENT 'id',
  `date` date NOT NULL COMMENT '鏃ユ湡',
  `train_code` varchar(20) NOT NULL COMMENT '杞︽?缂栧彿',
  `index` int NOT NULL COMMENT '绠卞簭',
  `seat_type` char(1) NOT NULL COMMENT '搴т綅绫诲瀷|鏋氫妇[SeatTypeEnum]',
  `seat_count` int NOT NULL COMMENT '搴т綅鏁',
  `row_count` int NOT NULL COMMENT '鎺掓暟',
  `col_count` int NOT NULL COMMENT '鍒楁暟',
  `create_time` datetime(3) DEFAULT NULL COMMENT '鏂板?鏃堕棿',
  `update_time` datetime(3) DEFAULT NULL COMMENT '淇?敼鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `date_train_code_index_unique` (`date`,`train_code`,`index`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='姣忔棩杞﹀帰';
/*!40101 SET character_set_client = @saved_cs_client */;

