DROP TABLE IF EXISTS `daily_train_seat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_train_seat` (
  `id` bigint NOT NULL COMMENT 'id',
  `date` date NOT NULL COMMENT '鏃ユ湡',
  `train_code` varchar(20) NOT NULL COMMENT '杞︽?缂栧彿',
  `carriage_index` int NOT NULL COMMENT '绠卞簭',
  `row` char(2) NOT NULL COMMENT '鎺掑彿|01, 02',
  `col` char(1) NOT NULL COMMENT '鍒楀彿|鏋氫妇[SeatColEnum]',
  `seat_type` char(1) NOT NULL COMMENT '搴т綅绫诲瀷|鏋氫妇[SeatTypeEnum]',
  `carriage_seat_index` int NOT NULL COMMENT '鍚岃溅绠卞骇搴',
  `sell` varchar(50) NOT NULL COMMENT '鍞?崠鎯呭喌|灏嗙粡杩囩殑杞︾珯鐢?1鎷兼帴锛?琛ㄧず鍙?崠锛?琛ㄧず宸插崠',
  `create_time` datetime(3) DEFAULT NULL COMMENT '鏂板?鏃堕棿',
  `update_time` datetime(3) DEFAULT NULL COMMENT '淇?敼鏃堕棿',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='姣忔棩搴т綅';
