DROP TABLE IF EXISTS `daily_train_station`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_train_station` (
  `id` bigint NOT NULL COMMENT 'id',
  `date` date NOT NULL COMMENT '鏃ユ湡',
  `train_code` varchar(20) NOT NULL COMMENT '杞︽?缂栧彿',
  `index` int NOT NULL COMMENT '绔欏簭',
  `name` varchar(20) NOT NULL COMMENT '绔欏悕',
  `name_pinyin` varchar(50) NOT NULL COMMENT '绔欏悕鎷奸煶',
  `in_time` time DEFAULT NULL COMMENT '杩涚珯鏃堕棿',
  `out_time` time DEFAULT NULL COMMENT '鍑虹珯鏃堕棿',
  `stop_time` time DEFAULT NULL COMMENT '鍋滅珯鏃堕暱',
  `km` decimal(8,2) NOT NULL COMMENT '閲岀▼锛堝叕閲岋級|浠庝笂涓?珯鍒版湰绔欑殑璺濈?',
  `create_time` datetime(3) DEFAULT NULL COMMENT '鏂板?鏃堕棿',
  `update_time` datetime(3) DEFAULT NULL COMMENT '淇?敼鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `date_train_code_index_unique` (`date`,`train_code`,`index`),
  UNIQUE KEY `date_train_code_name_unique` (`date`,`train_code`,`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='姣忔棩杞︾珯';
