DROP TABLE IF EXISTS `daily_train_ticket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_train_ticket` (
  `id` bigint NOT NULL COMMENT 'id',
  `date` date NOT NULL COMMENT '鏃ユ湡',
  `train_code` varchar(20) NOT NULL COMMENT '杞︽?缂栧彿',
  `start` varchar(20) NOT NULL COMMENT '鍑哄彂绔',
  `start_pinyin` varchar(50) NOT NULL COMMENT '鍑哄彂绔欐嫾闊',
  `start_time` time NOT NULL COMMENT '鍑哄彂鏃堕棿',
  `start_index` int NOT NULL COMMENT '鍑哄彂绔欏簭|鏈?珯鏄?暣涓?溅娆＄殑绗?嚑绔',
  `end` varchar(20) NOT NULL COMMENT '鍒拌揪绔',
  `end_pinyin` varchar(50) NOT NULL COMMENT '鍒拌揪绔欐嫾闊',
  `end_time` time NOT NULL COMMENT '鍒扮珯鏃堕棿',
  `end_index` int NOT NULL COMMENT '鍒扮珯绔欏簭|鏈?珯鏄?暣涓?溅娆＄殑绗?嚑绔',
  `ydz` int NOT NULL COMMENT '涓?瓑搴т綑绁',
  `ydz_price` decimal(8,2) NOT NULL COMMENT '涓?瓑搴хエ浠',
  `edz` int NOT NULL COMMENT '浜岀瓑搴т綑绁',
  `edz_price` decimal(8,2) NOT NULL COMMENT '浜岀瓑搴хエ浠',
  `rw` int NOT NULL COMMENT '杞?崸浣欑エ',
  `rw_price` decimal(8,2) NOT NULL COMMENT '杞?崸绁ㄤ环',
  `yw` int NOT NULL COMMENT '纭?崸浣欑エ',
  `yw_price` decimal(8,2) NOT NULL COMMENT '纭?崸绁ㄤ环',
  `create_time` datetime(3) DEFAULT NULL COMMENT '鏂板?鏃堕棿',
  `update_time` datetime(3) DEFAULT NULL COMMENT '淇?敼鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `date_train_code_start_end_unique` (`date`,`train_code`,`start`,`end`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='浣欑エ淇℃伅';
